 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    markers = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 3 and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        q.append((nx, ny))
            r0 = min(x for x, _ in cells)
            r1 = max(x for x, _ in cells)
            c0 = min(y for _, y in cells)
            c1 = max(y for _, y in cells)
            markers.extend((x, y) for x in range(r0, r1+1) for y in range(c0, c1+1) if grid[x][y] == 2)

    out = [row[:] for row in grid]
    for r, c in markers:
        for x in range(max(0, r-1), min(h, r+2)):
            for y in range(max(0, c-1), min(w, c+2)):
                if (x, y) != (r, c):
                    out[x][y] = 1
    return out
